// Verbatim tool objects from the python live capture (tools/list id=2).
// `do` is present (P2 seam); all five tool objects are verbatim captures.
pub const TOOL_SCREENSHOT: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"Capture the screen for a vision model. display=-1 whole virtual\ndesktop, 0..N one monitor (out of range -> error). window=<selector>\ncaptures that window side-effect-free (never restored/raised/focused)\nand wins over display. Selector grammar: \"123456\"|\"hwnd:123456\" hwnd,\n\"pid:<int>\", \"exe:<name>\" (with/without .exe), \"title:<substr>\",\n\"class:<name>\" (disambiguator), or bare text (exact title -> exact exe\n-> substring title -> substring exe). region=[left,top,right,bottom]\nin virtual-desktop px applies after the window crop. max_px (default\n1280) is a long-edge clamp, aspect-preserving, never upscaling; null\nreturns native pixels. fmt png|jpeg (jpg is an alias for jpeg); JPEG\nquality is clamped to 1-100, PNG ignores quality. grid=true overlays a\nlight 128px lattice. allow_crop_fallback=true permits a foreground-only\ndesktop crop to dwm_rect when PrintWindow refuses (default refuses).\nelements=true appends a THIRD content block: a compact JSON object\n{backend,truncated,rect_space,elements,uia_available,uia_error,\nfallback,empty,depth_capped,depth_limit} where elements lists the\nwindow's controls as {win,hwnd,role,name,auto_id,rect:[l,t,w,h],\ninvokable,path}. rect is in SCREEN coordinates so it composes with the\nsame coordinate_map formula above (source.x/y origin, source.w/h over\nimage.w/h). Anonymous layout nodes (no name, no auto_id, not\ninvokable) are dropped; the list caps at 200 entries with\ntruncated:true. backend names which element backend served this call:\n\"uia\" (UIAutomation COM walk via the local uiautomation package) or\n\"win32\" (EnumChildWindows/GetWindowText/GetClassName/GetWindowRect\nfallback when UIA yields nothing). An empty list is reported, not\nimplied: empty:true with an empty_reason, plus uia_available (was UIA\neven loadable) and fallback (which fallback ran). When the UIA\nrecursion cut-off (depth_limit 8) actually hides deeper controls,\ndepth_capped:true is set and truncated is true. With window=<selector>\nthe model covers that window, otherwise the current foreground window.\n\nReturns [image, coordinate_map_json] plus the element block when\nelements=true. Map model image px back with:\nscreen_x = source.x + round((img_x + 0.5) * source.w / image.w)\n(same for y). For window captures source.x/y equal the dwm_rect origin\nand source.kind is \"window\". Zoom path for small targets: pass a tight\nwindow/region with max_px=1280. Errors: [\"error: <code>: <detail>\"]\nwith codes bad_display|bad_region|bad_window|ambiguous_window|\nempty_crop|capture_failed. Never raises.","inputSchema":{"properties":{"display":{"default":-1,"type":"integer"},"region":{"anyOf":[{"items":{},"type":"array"},{"type":"null"}],"default":null},"window":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null},"max_px":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":1280},"fmt":{"default":"jpeg","type":"string"},"quality":{"default":80,"type":"integer"},"grid":{"default":false,"type":"boolean"},"allow_crop_fallback":{"default":false,"type":"boolean"},"elements":{"default":false,"type":"boolean"}},"type":"object","additionalProperties":false},"name":"screenshot","title":"Screenshot"}"#;
pub const TOOL_LIST_WINDOWS: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"List visible top-level windows as JSON:\n[{hwnd,pid,exe,title,class,rect:[l,t,r,b],dwm_rect,client_rect,\nminimized,maximized,foreground,cloaked,visible,dpi}].\nrect=GetWindowRect (compat, includes the invisible border);\ndwm_rect=DWMWA_EXTENDED_FRAME_BOUNDS (mapping truth, else rect with\ndwm_fallback:true); client_rect in screen space. Read-only: no focus\nchange, no window is touched.","inputSchema":{"properties":{},"type":"object","additionalProperties":false},"name":"list_windows","outputSchema":{"properties":{"result":{"type":"string"}},"required":["result"],"type":"object","x-fastmcp-wrap-result":true},"title":"List Windows"}"#;
pub const TOOL_WINDOW: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"Window control. action in focus|move|resize|minimize|maximize|restore|\nclose|topmost. Target by selector (hwnd:|pid:|exe:|title:|class:|bare\ndigits=hwnd, bare text=title/exe search, case-insensitive) or hwnd.\nmove needs x,y; resize needs width,height. Returns JSON {ok,...};\nambiguous matches return ok:false with a candidate list.","inputSchema":{"properties":{"action":{"type":"string"},"title":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null},"hwnd":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null},"x":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null},"y":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null},"width":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null},"height":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null}},"required":["action"],"type":"object","additionalProperties":false},"name":"window","outputSchema":{"properties":{"result":{"type":"string"}},"required":["result"],"type":"object","x-fastmcp-wrap-result":true},"title":"Window"}"#;
pub const TOOL_DO: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"BURST tool: execute queued input actions in ONE MCP round-trip.\nAction types: move|click|down|up|drag|scroll|type|key|hotkey|wait|\nwait_for|focus_window|invoke|set_value. Consecutive pure-input actions are coalesced\ninto a SINGLE SendInput call. wait/focus_window/wait_for flush pending\ninput first. Returns JSON with per-action {index,type,ok,ms[,mode]}\nplus total_ms, sendinput_calls, sendinput_ms, events, focus_before,\nfocus_after\n(and focus_restored when the guard runs, posted_messages plus\nbackground_note under background). sendinput_ms is the summed time\nspent inside the flush (SendInput blocking when live, INPUT-array\nassembly when dry_run) so a slow burst can be attributed without\ndeleting outliers (see burst-tail comment above def do). wait_for waits\nuntil the requested\ncondition is satisfied, polling inside the tool until it reaches a\nsatisfied state or the timeout expires:\n{\"type\":\"wait_for\",\"kind\":\"window_appear|window_disappear|pixel|\nstable\",\"selector\":...,\"x\":..,\"y\":..,\"color\":[r,g,b],\"tolerance\":..,\n\"region\":[l,t,r,b],\"timeout_ms\":..,\"poll_ms\":..}. A TIMEOUT IS NOT AN\nERROR: it returns ok:true with satisfied:false (the\nsatisfied/unsatisfied flag, never an error) so the rest of a batch\ncontinues; ok:false only for a malformed action. Per-action failures\nnever abort the burst: every action reports its own ok:false and the\nremaining actions still run (continue-always).\nbackground: a window selector (hwnd:|pid:|exe:|title:) delivering click/\ntype/key/hotkey/down/up by POSTING window messages (WM_LBUTTONDOWN/UP +\nWM_MOUSEMOVE, WM_CHAR, WM_KEYDOWN/UP) to that window with client-area\ncoordinates converted from the usual virtual-desktop px. The target is\nNEVER activated, focused, or raised. BACKGROUND MODE IS BEST-EFFORT:\nPostMessage input is not honoured by every app and is NOT equivalent to\nreal (SendInput) input. move/drag/scroll have no window-message\nequivalent and fail (ok:false) under background instead of silently doing\nnothing. Every background-delivered action reports mode:\"background\" plus\nthe resolved target hwnd.\nfocus_guard: when true and the foreground window changed during the call,\nthe entry foreground window is restored; focus_before/focus_after hwnds\nare always reported, plus focus_restored under the guard.\ninvoke: {\"type\":\"invoke\",\"element\":\"name:OK|auto_id:btnOk|path:0.1.2\",\n\"index\":0} activates one control from the structured element model of\nthe background target window (or the current foreground window when no\nbackground selector is given) through the pattern that element\nsupports: UIA Invoke/SelectionItem/Toggle, or a Win32 BM_CLICK under\nthe Win32 element fallback. It never moves the mouse and never changes\nthe foreground; a real pixel click happens ONLY with\n\"fallback\":\"click\", aimed at the element rect centre. When the selector\nmatches more than one element and no explicit index is given, invoke\ndoes NOT act: it returns ok:false with a candidates list\n[{name,role,auto_id,rect,ref}] so the caller can disambiguate; an explicit\nindex (even 0) acts on the nth match. Every invoke result names its\nactivation path in via\n(uia-invoke|uia-select|uia-toggle|win32-click|pixel-click|none) plus\nthe backend that served the element list and a resolution of\nfound|not-found|ambiguous|list-failed.\nset_value: {\"type\":\"set_value\",\"element\":\"name:OK|auto_id:100|path:0\",\n\"text\":\"...\"} writes text into one control from the same element model\nvia UIA ValuePattern.SetValue - no click, no coordinates, no focus\nchange. Selectors are name:|auto_id:|path: only (no ref:); ambiguous\nmatches return ok:false with a candidates list like invoke. Failures are\ntyped ok:false: element not found, element has no ValuePattern, element\nis read-only, or control re-resolution (stale path) failure; the Win32\nfallback has no ValuePattern and fails. Success reports the control\nacted on plus value_len (character count) and via uia-set-value - the\ntext value is never echoed (it may be a password). Under dry_run it\nresolves and reports value_len without firing.\ntype pacing: {\"type\":\"type\",\"text\":\"...\",\"chunk_chars\":64,\n\"chunk_ms\":15} splits a long type into one flush per chunk_chars chars\nwith a chunk_ms sleep between flushes (skipped under dry_run); absent\nchunk_chars keeps the single-coalesced behaviour exactly.\nclipboard: {\"type\":\"clipboard_set\",\"text\":\"...\"} writes CF_UNICODETEXT\nvia ctypes (no new dependency); {\"type\":\"clipboard_get\"} reads it back\nas {ok,text}. Clipboard content may hold secrets: treat get results as\nsensitive, never log or paste them beyond the caller.\ndry_run=true builds the exact INPUT array but calls SendInput ZERO times\n(metadata is still reported); invoke under dry_run still resolves the\nelement and reports found/not-found/ambiguous plus the path it would\nuse - it just never fires. For headless benchmarking without\ntouching the desktop.","inputSchema":{"properties":{"actions":{"items":{},"type":"array"},"background":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null},"focus_guard":{"default":false,"type":"boolean"},"settle_ms":{"default":0,"type":"integer"},"dry_run":{"default":false,"type":"boolean"}},"required":["actions"],"type":"object","additionalProperties":false},"name":"do","outputSchema":{"properties":{"result":{"type":"string"}},"required":["result"],"type":"object","x-fastmcp-wrap-result":true},"title":"Do"}"#;
pub const TOOL_CURSOR: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"Current cursor position + monitor rects as JSON:\n{x, y, screens:[[l,t,r,b],...]}.","inputSchema":{"properties":{},"type":"object","additionalProperties":false},"name":"cursor","outputSchema":{"properties":{"result":{"type":"string"}},"required":["result"],"type":"object","x-fastmcp-wrap-result":true},"title":"Cursor"}"#;
pub const TOOL_ELEMENTS: &str = r#"{"_meta":{"fastmcp":{"tags":[]}},"description":"List structured UI elements for a window as JSON, zero-pixel (no screenshot, no focus change, no input).\nTarget by selector (title text or hwnd, same grammar as the window tool). detail=true keeps the raw win and hwnd fields on each entry; default false returns the compact {ref,role,name,auto_id,rect,invokable,path} shape, omitting win (and hwnd on the Win32 fallback).\nEach entry carries a ref token \"<hwnd>.<path>\" (e.g. \"199210.0.3.1\"): a per-enumeration identifier for correlating entries between two listings, not a durable handle and not an identity guarantee - invoke re-enumerates and matches name:|auto_id:|path:, so a ref from an older listing can address a different control if the UI changed in between. Invoke accepts name:, auto_id:, and path: only; there is no ref-based invoke selector.\nReturns JSON {backend,truncated,rect_space,elements,uia_available,\nuia_error,fallback,empty[,empty_reason],depth_capped,depth_limit}, the same top-level object the screenshot elements block carries (per-entry shapes differ as above).","inputSchema":{"properties":{"title":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null},"hwnd":{"anyOf":[{"type":"integer"},{"type":"null"}],"default":null},"detail":{"default":false,"type":"boolean"}},"type":"object","additionalProperties":false},"name":"elements","outputSchema":{"properties":{"result":{"type":"string"}},"required":["result"],"type":"object","x-fastmcp-wrap-result":true},"title":"Elements"}"#;
